// Get search criteria from AI
const searchEmail = $input.item.json.searchEmail || '';
const searchName = $input.item.json.searchName || '';
const searchCompany = $input.item.json.searchCompany || '';

// Get all rows from Google Sheets
const allContacts = $input.all();

// Filter based on criteria
const filtered = allContacts.filter(contact => {
  const data = contact.json;

  // Email match (exact or partial)
  if (searchEmail && data['Email Address']) {
    if (data['Email Address'].toLowerCase().includes(searchEmail.toLowerCase())) {
      return true;
    }
  }

  // Name match (partial)
  if (searchName && data['Full Name']) {
    if (data['Full Name'].toLowerCase().includes(searchName.toLowerCase())) {
      return true;
    }
  }

  // Company match (partial)
  if (searchCompany && data['Company Name']) {
    if (data['Company Name'].toLowerCase().includes(searchCompany.toLowerCase())) {
      return true;
    }
  }

  // If no search criteria, return all
  if (!searchEmail && !searchName && !searchCompany) {
    return true;
  }

  return false;
});

return filtered;
